Graphics.prototype.setFontAnton = function(scale) {
  // Actual height 69 (68 - 0)
  g.setFontCustom(atob(""), 46, atob("EiAnGicnJycnJycnEw=="), 78 + (scale << 8) + (1 << 16));
};

const pag_svc = "23210001-28d5-4b7b-bad0-7dee1eee1b6d";

let setMinutes = 45;
let isRunning = false;
let hasStarted = false; // true once the match has been started at least once
let startTime = null;   // Date.now() when the timer was last (re)started
let runBase = 0;        // ms of match time accumulated in previous run segments
let preloadMs = 0;      // elapsed time preloaded before kick-off (second half)
let timeUpBuzzed = false;
let drawTimer = null;
let buzzTimer = null;
let flashTimers = [null, null];
let AR1shown = false;
let AR2shown = false;

// Two AR slots (store advertiser MACs)
let AR1addr = null;
let AR2addr = null;

// x position of the AR1 label - clear of the back icon in the top-left corner
const AR1_X = 30;
// Height of the AR label strip; nothing below it is part of a tap zone
const TOP_H = 40;
// Touches at or below this y hit the count-up (elapsed) display, above it
// (but below TOP_H) they hit the countdown (interval) display
const ELAPSED_ZONE_Y = 124;

// Colours come from g.theme, read at draw time. The settings app reloads the
// running app when the global theme changes, so no live listener is needed.
function flashBg() { return g.theme.dark ? "#ff0" : "#00f"; }
function flashFg() { return g.theme.dark ? "#000" : "#fff"; }

// Match time only (drives the countdown) - excludes any preloaded elapsed time
function getRunSecs() {
  let ms = runBase;
  if (isRunning) ms += Date.now() - startTime;
  return Math.floor(ms / 1000);
}

// Total elapsed shown on the count-up clock (preload + match time)
function getElapsed() {
  return Math.floor(preloadMs / 1000) + getRunSecs();
}

// Idle means "never started or fully reset" - the only state in which the
// interval and the second-half preload may be changed
function isIdle() {
  return !isRunning && !hasStarted;
}

function formatTime(secs) {
  let mins = Math.floor(secs / 60);
  let sec = secs % 60;
  return `${("0" + mins).slice(-2)}:${("0" + sec).slice(-2)}`;
}

function draw() {
  let remaining = setMinutes * 60 - getRunSecs();
  if (remaining < 0) remaining = 0;

  g.setBgColor(g.theme.bg);
  g.clearRect(0, TOP_H, g.getWidth(), g.getHeight());

  // Count Down
  g.setFontAnton(1);
  g.setFontAlign(0, 0);
  g.setColor(g.theme.fg);
  g.drawString(formatTime(remaining), g.getWidth() / 2, g.getHeight() / 2);

  // Count Up - keeps going past 00:00 (stoppage time)
  g.setFont("6x8", 4);
  g.setFontAlign(0, 0);
  g.setColor(g.theme.fg);
  g.drawString(formatTime(getElapsed()), g.getWidth() / 2, g.getHeight() / 2 + 60);

  if (AR1addr != null && !AR1shown) {
    drawAR1();
    AR1shown = true;
  }
  if (AR2addr != null && !AR2shown) {
    drawAR2();
    AR2shown = true;
  }
}

function tick() {
  if (isRunning && !timeUpBuzzed && getRunSecs() >= setMinutes * 60) {
    timeUpBuzzed = true;
    Bangle.buzz(); // full time - the count-up carries on as stoppage time
  }
  draw();
}

function touchHandle(_, xy) {
  // The clocks can only be set up before the match has started (never
  // started or fully reset) - not during a mid-match pause
  if (!isIdle()) return;
  const y = xy ? xy.y : 0;
  if (y < TOP_H) return; // AR label strip - not a tap zone
  if (y >= ELAPSED_ZONE_Y) {
    // Count-up display: toggle the second-half preload on/off. Repeated taps
    // never stack - it is either 00:00 or the selected interval.
    preloadMs = preloadMs ? 0 : setMinutes * 60000;
  } else {
    // Countdown display: cycle the half length
    setMinutes += 5;
    if (setMinutes > 45) setMinutes = 10;
    // Keep an active preload in step with the newly selected interval
    if (preloadMs) preloadMs = setMinutes * 60000;
  }
  draw();
}

function buttonHandle() {
  if (isRunning) {
    runBase += Date.now() - startTime;
    isRunning = false;
    if (drawTimer) {
      clearInterval(drawTimer);
      drawTimer = null;
    }
  } else {
    startTime = Date.now();
    isRunning = true;
    hasStarted = true;
    if (!drawTimer) drawTimer = setInterval(tick, 1000);
  }
  draw();
}

function drawAR1() {
  // Draw "AR1" in top-left
  g.setFont("6x8", 3);
  g.setFontAlign(-1, -1); // Align top-left
  g.setColor(g.theme.fg);
  g.drawString("AR1", AR1_X, 5);
}

function drawAR2() {
  // Draw "AR2" in top-right
  g.setFont("6x8", 3);
  g.setFontAlign(1, -1); // Align top-right
  g.setColor(g.theme.fg);
  g.drawString("AR2", g.getWidth() - 5, 5);
}

function flashAR1(state) {
  const x = AR1_X, y = 5;
  const text = "AR1";
  const scale = 3;

  g.setFont("6x8", scale);
  g.setFontAlign(-1, -1);

  const w = g.stringWidth(text);
  const h = 8 * scale;

  // Background - a theme-relative accent while lit, theme bg while dark
  g.setColor(state ? flashBg() : g.theme.bg);
  g.fillRect(x, y, x + w, y + h);

  // Text
  g.setColor(state ? flashFg() : g.theme.fg);
  g.drawString(text, x, y);
}

function flashAR2(state) {
  const text = "AR2";
  const scale = 3;

  g.setFont("6x8", scale);
  g.setFontAlign(1, -1); // Right-aligned, top
  const w = g.stringWidth(text);
  const h = 8 * scale;
  const x = g.getWidth() - 5;
  const y = 5;

  // Background - a theme-relative accent while lit, theme bg while dark
  g.setColor(state ? flashBg() : g.theme.bg);
  g.fillRect(x - w, y, x, y + h);

  // Text
  g.setColor(state ? flashFg() : g.theme.fg);
  g.drawString(text, x, y);
}

function startFlashingAR(AR) {
  const idx = AR - 1;
  if (flashTimers[idx]) return; // already flashing
  let state = true;
  let count = 0;
  const maxFlashes = 6; // 3s at 500ms per state change

  flashTimers[idx] = setInterval(() => {
    if (AR == 1) flashAR1(state);
    else flashAR2(state);
    state = !state;
    count++;
    if (count >= maxFlashes) {
      clearInterval(flashTimers[idx]);
      flashTimers[idx] = null;
      // restore the normal label
      g.setColor(g.theme.bg);
      if (AR == 1) {
        g.fillRect(AR1_X, 5, AR1_X + g.stringWidth("AR1"), 5 + 24);
        drawAR1();
      } else {
        g.fillRect(g.getWidth() - 5 - g.stringWidth("AR2"), 5, g.getWidth() - 5, 5 + 24);
        drawAR2();
      }
    }
  }, 500);
}

function normMac(id) {
  // setScan gives d.id as the advertiser address; keep it robust if suffix exists
  if ("string" != typeof id) return "";
  return id.split(" ")[0];
}

// Double-tap pattern for "added"
function buzzAdded() {
  // two short pulses
  return Bangle.buzz(120, 1).then(() => new Promise(r => setTimeout(r, 120)))
    .then(() => Bangle.buzz(120, 1));
}

// Haptics
const BUZZ_KNOWN_MS = 4000;
const BUZZ_COOLDOWN_MS = 6000; // slightly > BUZZ_KNOWN_MS
let lastBuzzAt = 0;

function buzzAllowed(fn) {
  const now = Date.now();
  if (now - lastBuzzAt < BUZZ_COOLDOWN_MS) return false;
  lastBuzzAt = now;
  fn();
  return true;
}

// AR1: long alert
function buzzKnownAR1() {
  Bangle.buzz(BUZZ_KNOWN_MS, 1);
}

// AR2: burst of very short taps
function buzzKnownAR2() {
  let count = 0;
  const taps = 20;

  if (buzzTimer) clearInterval(buzzTimer);
  buzzTimer = setInterval(() => {
    Bangle.buzz(60, 1);
    count++;
    if (count >= taps) {
      clearInterval(buzzTimer);
      buzzTimer = null;
    }
  }, 120); // short gap between taps
}

function initScan() {
  NRF.setScan(); // ensure only one scan is active

  // Espruino runs this callback from the event loop, so it is not
  // reentrant and needs no locking
  NRF.setScan(function (d) {
    const mac = normMac(d && d.id);
    if (!mac) return; // malformed/empty advertisement

    // If it's one of our saved devices, alert + flash its AR label
    if (mac === AR1addr) {
      if (buzzAllowed(buzzKnownAR1)) startFlashingAR(1);
      return;
    }
    if (mac === AR2addr) {
      if (buzzAllowed(buzzKnownAR2)) startFlashingAR(2);
      return;
    }

    // New devices
    if (!AR1addr) {
      AR1addr = mac;
      lastBuzzAt = Date.now(); // suppress immediate known-buzz
      buzzAdded();
      draw();
      return;
    }
    if (!AR2addr) {
      AR2addr = mac;
      lastBuzzAt = Date.now(); // suppress immediate known-buzz
      buzzAdded();
      draw();
      return;
    }
    // Third unique device: ignore
  }, {
    phy: "coded", // needs firmware 2v26+; extended is enabled automatically
    active: false, // passive scan
    filters: [{
      services: [pag_svc]
    }]
  });
}

function cleanup() {
  if (drawTimer) {
    clearInterval(drawTimer);
    drawTimer = null;
  }
  if (buzzTimer) {
    clearInterval(buzzTimer);
    buzzTimer = null;
  }
  flashTimers.forEach((t, i) => {
    if (t) {
      clearInterval(t);
      flashTimers[i] = null;
    }
  });
  isRunning = false;
  NRF.setScan(); // stop scanning
  // setLCDTimeout(0) keeps the screen on - restore the user's setting
  Bangle.setLCDTimeout((require("Storage").readJSON("setting.json", 1) || {}).timeout || 10);
}

function initUI() {
  g.clear(1); // reset graphics state to the current global theme
  Bangle.setUI({
    mode: "custom",
    back: function () { // top-left exit icon; coexists with btn
      cleanup();
      load();
    },
    btn: buttonHandle,
    touch: touchHandle,
    remove: cleanup
  });
  draw();
}

// --- Initialize ---
initUI();
Bangle.setLCDTimeout(0); // keep the screen on during the match
NRF.setTxPower(8);
initScan();
